  "contradictions": [
    "Кандидат утверждает, что совместно производится до 80% европейского кино, тогда как эталон указывает до 70%."
  ],
  "unsupported_claims": [
    "Утверждение, что в Европе совместно производится до 80% кино, не подтверждается цитатой, где указано до 70%."
  ],
  "supported_by_citations": false,
  "comment": "Кандидат исказил процент: вместо «до 70%» указано «до 80%», что противоречит обязательному факту и не подтверждается цитатой."
}

